create function public.claim_notifications()returns setof public.notification_outbox language plpgsql security definer set search_path=public as $$begin return query update public.notification_outbox set status='sending',attempts=attempts+1,locked_at=now()where id in(select o.id from public.notification_outbox o join public.notification_preferences p on p.user_id=o.user_id and p.email_enabled where(o.status in('pending','failed')or(o.status='sending'and o.locked_at<now()-interval '10 minutes'))and o.attempts<5 and(o.locked_at is null or o.locked_at<now()-interval '5 minutes')order by o.created_at for update of o skip locked limit 25)returning notification_outbox.*;end$$;
revoke all on function public.claim_notifications()from public,anon,authenticated;grant execute on function public.claim_notifications()to service_role;
